import esm  # pip install fair-esm==2.0.0
import esm2quinox
import jax
import numpy as np


def main():
    sequence = ""
    torch_model, alphabet = esm.pretrained.esm2_t6_8M_UR50D()
    model = esm2quinox.from_torch(torch_model)
    proteins = esm2quinox.tokenise([sequence])
    logits = jax.vmap(model)(proteins).logits
    output_ids = np.argmax(logits.squeeze(0)[1:-1], axis=-1)

    input_ids = proteins.squeeze(0)[1:-1]
    accuracy = (input_ids == output_ids).mean()
    print(f"Reconstruction accuracy: {accuracy:.2f}")
    print("I:", input_ids[:50])
    print("O:", output_ids[:50])


if __name__ == "__main__":
    main()
